const items = $input.all();
const results = [];

const sqlEscape = (str) => {
  if (!str) return null;
  return String(str).replace(/'/g, "''");
};

for (const item of items) {
  const data = item.json;
  if (!data.id) continue;

  const rawEmail = data.email_address ? data.email_address.trim() : null;
  const email = (rawEmail && !rawEmail.includes('@linkedin.user')) ? rawEmail : null;
  const company = data.company ? data.company.trim() : '';
  const domain = company ? company.toLowerCase().replace(/[^a-z0-9]/g, '') + '.com' : null;

  results.push({
    json: {
      connection_id: data.id,
      first_name: data.first_name || '',
      last_name: data.last_name || '',
      email: email,
      company: company,
      domain: domain,
      position: data.position || '',
      profile_url: data.profile_url || '',
      source: 'linkedin_connection',
      sql_connection_id: sqlEscape(data.id),
      sql_first_name: sqlEscape(data.first_name || ''),
      sql_last_name: sqlEscape(data.last_name || ''),
      sql_email: email ? sqlEscape(email) : null,
      sql_company: company ? sqlEscape(company) : null,
      sql_domain: domain ? sqlEscape(domain) : null,
      sql_position: sqlEscape(data.position || ''),
      sql_profile_url: sqlEscape(data.profile_url || '')
    }
  });
}

return results;
